    if new_tip["height"] < old_tip["height"]:
        return False
    if new_tip["height"] == old_tip["height"]:
        return (
            new_tip["tip_hash"] == old_tip["tip_hash"]
            and old_tip["status"] == STATUS_PENDING
            and new_tip["status"] == STATUS_CONFIRMED
